pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, uint256 netmCalls) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        netmCalls = bound(netmCalls, 1, 100);

        address originalOwner = c.owner();
        vm.assume(nonOwner != originalOwner);

        vm.startPrank(nonOwner);
