pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker) public {
        vm.assume(attacker != address(0));
        // Record original owner's balance before any manipulation
        address originalOwner = c.owner();
        uint256 balBefore = c.balanceOf(originalOwner);

        // attacker calls NETM, which in the buggy version sets owner = attacker (since onlyOwner is empty)
        // In reference, this call reverts unless attacker is the original owner, so we use try/catch to handle both paths
        bool success;
        try c.NETM() { success = true; } catch { success = false; }

        if (success) {
            // If call succeeded, attacker is now owner in the buggy version.
            // Attacker then transfers ownership to themselves to ensure full control.
            vm.prank(attacker);
            c.transferOwnership(attacker);
            // Now attacker can call burn to manipulate totalDistributed/balances
            // We check that balances[originalOwner] remains unchanged because in reference, this entire sequence is impossible.
            uint256 balAfter = c.balanceOf(originalOwner);
            assertTrue(balAfter == balBefore);
        } else {
            // In reference, call always fails for non-owner; property holds vacuously (balAfter == balBefore)
            assertTrue(true);
        }
    }
}

