pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address originalOwner) public {
        vm.assume(nonOwner != originalOwner);
        vm.assume(nonOwner != address(0));
        vm.assume(originalOwner != address(0));
        // Set up state: originalOwner is the initial owner (msg.sender in constructor)
        // We need to make originalOwner the owner. The constructor sets owner = msg.sender,
        // but during setUp() msg.sender is this test contract. We can transfer ownership.
        vm.prank(address(this)); // this test contract is the initial owner
        c.transferOwnership(originalOwner);
        // Now originalOwner is the owner. Record their initial balance.
        uint256 initialBalance = c.balanceOf(originalOwner);
        // A non-owner attempts to call NETM
        vm.prank(nonOwner);
        try c.NETM() { } catch { }
        // After call, assert that originalOwner's balance remains unchanged
        uint256 finalBalance = c.balanceOf(originalOwner);
        assertTrue(finalBalance == initialBalance);
    }
}

