pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address originalOwner;

    function setUp() public {
        c = new C();
        originalOwner = address(0xbeef);
        vm.prank(originalOwner);
        c.NETM();
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != originalOwner);
        vm.assume(caller != address(0));

        uint256 balanceBefore = c.balanceOf(originalOwner);

        vm.prank(caller);
        c.NETM();

        uint256 balanceAfter = c.balanceOf(originalOwner);
        assertEq(balanceAfter, balanceBefore);
    }
}

