pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCandidate) public {
        // Restrict to a non-zero address for ownership
        vm.assume(ownerCandidate != address(0));
        // Set the caller to be the ownerCandidate
        vm.prank(ownerCandidate);
        c.transferOwnership(ownerCandidate);
        // Record total supply before NETM, which is fixed
        uint256 totalBefore = c.totalSupply();
        // Call NETM as the new owner
        vm.prank(ownerCandidate);
        c.NETM();
        // Calculate sum of balances of two potentially affected addresses
        uint256 sumAfter = c.balanceOf(ownerCandidate) + c.balanceOf(address(0));
        // The invariant: total supply must always be at least the sum of these two balances
        // The mutant fails because ownerCandidate's balance is not set, reducing the sum
        assertTrue(totalBefore >= sumAfter);
    }
}

