pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // actor must not be the zero address and must not be the deployer (owner)
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // prank as the owner (deployer) to call NETM
        vm.prank(address(this));
        c.NETM();
        // after NETM, balances[owner] should be totalDistributed and balances[actor] should be 0
        uint256 ownerBalance = c.balanceOf(address(this));
        uint256 actorBalance = c.balanceOf(actor);
        uint256 totalDist = 250000000e18;
        assertTrue(ownerBalance == totalDist && actorBalance == 0);
    }
}

